import{_ as a}from"./chunks/daily-2026-08-11-durable-event-identity-terminal-evidence-figure.D90658L1.js";import{_ as i,C as n,o as r,c as o,E as s,a2 as c}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse('{"title":"Agent Operations Need Durable Identity and Explicit Terminal Evidence","description":"","frontmatter":{"title":"Agent Operations Need Durable Identity and Explicit Terminal Evidence","date":"2026-08-11","column":"open-source-engineering","category":"daily","summary":"Stable occurrence identity should be created before asynchronous handoff and reused across retries, while typed terminal success/error evidence closes that same logical execution. Deduplication identity improves reconciliation but does not prove system-wide exactly-once or lossless delivery.","sources":["research/analysis/Q-20260811-03-event-identity-terminal-evidence.md","research/reading/Q-20260811-03-durable-event-identity-terminal-evidence.md"],"item_id":"Q-20260811-03","lifecycle":"Published","source_research_object":"research/analysis/Q-20260811-03-event-identity-terminal-evidence.md","source_reading_result":"research/reading/Q-20260811-03-durable-event-identity-terminal-evidence.md","cover":"/assets/covers/daily-2026-08-11-durable-event-identity-terminal-evidence.webp","visualization":"/assets/covers/daily-2026-08-11-durable-event-identity-terminal-evidence-figure.svg","visualization_decision":"Required — editorial identity/terminal metaphor plus a separate retry-and-terminal evidence figure","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"en/engineering/2026-08-11-durable-event-identity-terminal-evidence.md","filePath":"en/engineering/2026-08-11-durable-event-identity-terminal-evidence.md","lastUpdated":1786455324000}'),d={name:"en/engineering/2026-08-11-durable-event-identity-terminal-evidence.md"};function l(u,e,m,h,p,y){const t=n("ArticleCover");return r(),o("div",null,[s(t,{image:"/assets/covers/daily-2026-08-11-durable-event-identity-terminal-evidence.webp",kicker:"Open-source Engineering · Daily Research",title:"Agent Operations Need Durable Identity and Explicit Terminal Evidence",summary:"Stable occurrence identity should be created before asynchronous handoff and reused across retries, while typed terminal success/error evidence closes that same logical execution. Deduplication identity improves reconciliation but does not prove system-wide exactly-once or lossless delivery.",version:"Q-20260811-03",status:"Daily Runtime V5 · 2026-08-11",languageHref:"/zh/engineering/2026-08-11-durable-event-identity-terminal-evidence",languageLabel:"中文"}),e[0]||(e[0]=c('<h1 id="agent-operations-need-durable-identity-and-explicit-terminal-evidence" tabindex="-1">Agent Operations Need Durable Identity and Explicit Terminal Evidence <a class="header-anchor" href="#agent-operations-need-durable-identity-and-explicit-terminal-evidence" aria-label="Permalink to &quot;Agent Operations Need Durable Identity and Explicit Terminal Evidence&quot;">​</a></h1><p>Distributed agent systems often confuse three different properties: “this logical occurrence has an identity,” “the transport did not duplicate a row,” and “the business operation executed exactly once.” They are not equivalent. A durable occurrence ID is primarily a reconciliation primitive; terminal evidence is what closes the logical execution.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>A merged Google ADK analytics change creates a stable <code>event_id</code> before asynchronous delivery, reuses that same ID across retries, introduces an opt-in committed-stream mode with explicit offsets, and adds explicit terminal metadata for final LLM responses and workflow-node success/error events.</p><p>The same implementation also documents the limits of its guarantee: duplicate physical rows remain possible in the default path, committed-stream recovery can still drop rows under retry exhaustion, offset conflict or stream-rotation failure, and offset/desynchronization state shown in the implementation is process-local rather than demonstrated as restart-safe.</p><p>The Research Center judgment is therefore precise: <strong>allocate durable occurrence identity before asynchronous handoff, reuse it across retries, and emit typed terminal evidence tied to the same logical execution. Do not call that end-to-end exactly-once unless every layer that owns the guarantee can prove it.</strong></p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>The primary source is merged Google ADK implementation commit <code>04b8b72709f6d17b503cf674c8ac1b89798f655e</code>:</p><ul><li><a href="https://github.com/google/adk-python/commit/04b8b72709f6d17b503cf674c8ac1b89798f655e" target="_blank" rel="noreferrer">https://github.com/google/adk-python/commit/04b8b72709f6d17b503cf674c8ac1b89798f655e</a></li></ul><p>The same-day Reading Result records the writer state machine, retry behavior, offset-conflict handling, drop boundaries, final-only LLM termination metadata and explicit <code>NODE_OUTPUT</code> / <code>NODE_ERROR</code> evidence.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>The implementation assigns <code>event_id</code> when an analytics row is created, before it enters the asynchronous write path. Because retries resend the same row, the same occurrence identity survives ambiguous transport retries. In the default mode this does not prevent duplicate physical rows; it makes them identifiable for query-time deduplication.</p><p>The optional committed-stream mode adds explicit offsets and local conflict handling. Ambiguous retries can be confirmed when an occupied offset follows a locally ambiguous send, but an unexpected occupied offset marks the stream desynchronized. Rotation failure and backoff are deliberately bounded, and the implementation explicitly documents row-loss cases rather than claiming a lossless system.</p><p>Terminal evidence is also made more explicit. Final LLM finish metadata is emitted only on the final response row, while workflow nodes can emit dedicated <code>NODE_OUTPUT</code> and <code>NODE_ERROR</code> events with run/node identity. Progressive telemetry and terminal outcome are therefore separate evidence classes.</p><p><img src="'+a+'" alt="Durable identity and terminal evidence figure"></p><p><em>Figure 1. A logical identity is created before asynchronous handoff and reused across retries; explicit success or failure evidence closes that same logical execution. Source: Research Center synthesis based on the cited primary sources.</em></p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mechanism</th><th>What it improves</th><th>What remains unproven</th><th>Evidence class</th></tr></thead><tbody><tr><td>Stable <code>event_id</code> before enqueue</td><td>Retry/duplicate reconciliation</td><td>Storage-level exactly-once</td><td>Merged implementation + tests</td></tr><tr><td>Reuse same ID on retry</td><td>Logical occurrence continuity</td><td>External side-effect idempotency</td><td>Merged implementation + tests</td></tr><tr><td>Committed stream + offsets</td><td>Narrows ambiguous duplicate behavior in one live writer</td><td>Restart-safe, lossless delivery</td><td>Merged implementation; explicit loss boundaries</td></tr><tr><td>Typed terminal events</td><td>Queryable success/error closure</td><td>Semantic completeness of every business outcome</td><td>Merged implementation + tests</td></tr><tr><td>Drop/conflict counters</td><td>Makes ambiguity visible</td><td>Automatic business recovery</td><td>Implementation + Research Center interpretation</td></tr></tbody></table><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>Identity and guarantee scope must remain separate. A unique event ID does not stop a downstream sink from receiving two physical copies; it only lets consumers recognize that the copies represent the same logical occurrence. Similarly, a transport that deduplicates analytics rows cannot prove that an external tool call or business transaction ran exactly once.</p><p>This matters for Runtime governance. If one task is retried after a timeout, the retry should preserve the logical occurrence identity while generating additional physical delivery-attempt evidence. The terminal event should name the same occurrence ID and clearly state success, failure, cancellation or externally handed-off outcome.</p><p>A quiet stream is not sufficient evidence either. If rows may be dropped during conflict recovery, the runtime needs positive terminal evidence plus ambiguity/drop counters. Absence of an error row cannot be treated as proof that nothing failed.</p><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><p>For Digital Employees, create one durable occurrence ID before a work item, tool call or connector action crosses an asynchronous boundary. Preserve it across retry and recovery. Emit explicit terminal success, failure, cancellation and external-handoff events rather than inferring closure from silence.</p><p>For CodeFlowMu, add stable event IDs to Runtime timeline, report and evidence records, but keep physical delivery identity separate from logical occurrence identity. Retry-exhausted, offset-conflict, duplicate and dropped-event counters should be retained as governance evidence even if a later recovery succeeds.</p><p>For TMPA, the implementation is useful evidence for append-only provenance and explicit terminal-state semantics, but a single analytics plugin cannot establish end-to-end exactly-once guarantees for protocol-level claims.</p><h2 id="boundaries-and-uncertainty" tabindex="-1">Boundaries and uncertainty <a class="header-anchor" href="#boundaries-and-uncertainty" aria-label="Permalink to &quot;Boundaries and uncertainty&quot;">​</a></h2><p>The selected implementation explicitly does not establish lossless delivery under all failures. Durable offset reconstruction after process restart is not demonstrated. The analytics <code>event_id</code> identifies emitted analytics occurrences, not arbitrary external business actions. <code>NODE_OUTPUT</code> / <code>NODE_ERROR</code> improve observability but do not prove every workflow node emits a semantically complete business result.</p><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><p>Agent runtimes should define an identity hierarchy that connects Runtime task, worker claim, tool/action attempt and emitted evidence without conflating them. Restart recovery should specify how durable occurrence identity interacts with local offset or retry state, and operational policy should define when duplicate/conflict/drop counters trigger alerting, quarantine or governed re-execution.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The header cover uses one persistent identity marker passing through disruption into a terminal evidence chamber. The figure embedded in the Observation section explains identity creation, retry reuse, explicit terminal success/error and downstream reconciliation. Both are Research Center originals and contain no invented quantitative data.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Google, <code>adk-python</code>, merged analytics implementation commit <code>04b8b72709f6d17b503cf674c8ac1b89798f655e</code>: <a href="https://github.com/google/adk-python/commit/04b8b72709f6d17b503cf674c8ac1b89798f655e" target="_blank" rel="noreferrer">https://github.com/google/adk-python/commit/04b8b72709f6d17b503cf674c8ac1b89798f655e</a></li><li>Research Center Research Object: <code>research/analysis/Q-20260811-03-event-identity-terminal-evidence.md</code></li><li>Research Center Reading Result: <code>research/reading/Q-20260811-03-durable-event-identity-terminal-evidence.md</code></li></ol><blockquote><p>Publication status: Released after the Publication gate; article content is unchanged from the completed Production Candidate.</p></blockquote>',35))])}const g=i(d,[["render",l]]);export{v as __pageData,g as default};
